/* Refresh the CSRF token right before submitting, so a login page left open for hours,
   restored from history or opened before a deploy never fails with "page expired". */
(()=>{const url=@json(route('member.csrf-token'));document.querySelectorAll('form[method="post"]').forEach(form=>form.addEventListener('submit',async event=>{if(form.dataset.fresh==='1'){return}event.preventDefault();if(form.dataset.busy==='1')return;form.dataset.busy='1';const button=form.querySelector('button');if(button)button.disabled=true;try{const res=await fetch(url,{credentials:'same-origin',cache:'no-store',headers:{Accept:'application/json'}});if(res.ok){const data=await res.json();form.querySelectorAll('input[name="_token"]').forEach(input=>input.value=data.token)}}catch(e){}form.dataset.fresh='1';HTMLFormElement.prototype.submit.call(form)}));window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()})})();
</script></body></html>
